"""Intent tests for M1-T14: the corridor environment (TC-11, CORE-03)."""

import json
from pathlib import Path
from typing import Any

import numpy as np
import pytest

from rllab.core import SOLO, Rewards, StepResult
from rllab.envs import Corridor

ROOT = Path(__file__).resolve().parents[3]
FIXTURE = ROOT / "tests" / "fixtures" / "rllab" / "TC-11"
REWARDS_SAMPLES = ROOT / "tests" / "contracts" / "core.Rewards" / "samples"


def _load(path: Path) -> Any:
    return json.loads(path.read_text())


@pytest.fixture
def tc11() -> tuple[dict[str, Any], dict[str, Any]]:
    return _load(FIXTURE / "input.json"), _load(FIXTURE / "expected.json")


def _make(inputs: dict[str, Any], rewards: Rewards | None = None) -> Corridor:
    if rewards is None:
        return Corridor(length=inputs["length"], max_steps=inputs["max_steps"])
    return Corridor(length=inputs["length"], max_steps=inputs["max_steps"], rewards=rewards)


def _act(env: Corridor, action: int) -> StepResult:
    return env.step({SOLO: np.array([action], dtype=np.int64)})


def _position(obs: dict[str, np.ndarray]) -> int:
    return int(np.argmax(obs[SOLO][0]))


@pytest.mark.intent
def test_tc11_a_right_eight_times_then_goal(
    tc11: tuple[dict[str, Any], dict[str, Any]],
) -> None:
    inputs, expected = tc11
    seq = inputs["sequences"]["a"]
    env = _make(inputs)
    env.reset(0)
    result: StepResult | None = None
    for action in seq[:8]:
        result = _act(env, action)
        assert not result.terminated
        assert not result.truncated
    assert result is not None
    assert _position(result.obs) == expected["a"]["position_after_8"]
    final = _act(env, seq[8])
    assert float(final.reward[SOLO][0]) == expected["a"]["final_reward"]
    assert final.terminated is expected["a"]["terminated"]
    assert final.truncated is False
    assert final.info["steps"] == expected["a"]["steps"]
    assert bool(final.done[SOLO][0]) is True


@pytest.mark.intent
def test_tc11_a_goal_reward_is_rewards_food(
    tc11: tuple[dict[str, Any], dict[str, Any]],
) -> None:
    inputs, _ = tc11
    sample = _load(REWARDS_SAMPLES / "food_ten.json")
    env = _make(inputs, Rewards(**sample))
    env.reset(0)
    final: StepResult | None = None
    for action in inputs["sequences"]["a"]:
        final = _act(env, action)
    assert final is not None
    assert final.terminated is True
    assert float(final.reward[SOLO][0]) == sample["food"]


@pytest.mark.intent
def test_tc11_b_left_at_start_leaves_observation_unchanged(
    tc11: tuple[dict[str, Any], dict[str, Any]],
) -> None:
    inputs, expected = tc11
    env = _make(inputs)
    obs0, _ = env.reset(0)
    start = obs0[SOLO].copy()
    result = _act(env, inputs["sequences"]["b"][0])
    unchanged = bool(np.array_equal(result.obs[SOLO], start))
    assert unchanged is expected["b"]["observation_unchanged"]
    assert not result.terminated
    assert not result.truncated


@pytest.mark.intent
def test_tc11_c_fifty_lefts_truncate_on_step_fifty(
    tc11: tuple[dict[str, Any], dict[str, Any]],
) -> None:
    inputs, expected = tc11
    spec = inputs["sequences"]["c"]
    env = _make(inputs)
    env.reset(0)
    truncated_at: int | None = None
    last: StepResult | None = None
    for i in range(1, spec["n_steps"] + 1):
        last = _act(env, spec["repeat_action"])
        if last.truncated:
            truncated_at = i
            break
    assert truncated_at == expected["c"]["truncated_at_step"]
    assert last is not None
    assert last.terminated is expected["c"]["terminated"]
    assert last.info["steps"] == expected["c"]["truncated_at_step"]


@pytest.mark.intent
def test_corridor_shape_contract(
    tc11: tuple[dict[str, Any], dict[str, Any]],
) -> None:
    inputs, _ = tc11
    length = inputs["length"]
    env = _make(inputs)
    assert list(env.teams) == [SOLO]
    assert env.board == "grid"
    obs, info = env.reset(0)
    assert obs[SOLO].shape == (1, length)
    assert obs[SOLO].dtype == np.float32
    assert float(obs[SOLO].sum()) == 1.0
    assert info["steps"] == 0
    frame = env.frame()
    assert frame.shape == (1, length)
    assert frame.dtype == np.int8


@pytest.mark.intent
def test_corridor_step_after_game_over_raises(
    tc11: tuple[dict[str, Any], dict[str, Any]],
) -> None:
    inputs, _ = tc11
    env = _make(inputs)
    env.reset(0)
    for action in inputs["sequences"]["a"]:
        _act(env, action)
    with pytest.raises(RuntimeError):
        _act(env, 1)


@pytest.mark.intent
def test_corridor_action_out_of_range_raises(
    tc11: tuple[dict[str, Any], dict[str, Any]],
) -> None:
    inputs, _ = tc11
    env = _make(inputs)
    env.reset(0)
    with pytest.raises(ValueError):
        _act(env, 2)

